 "<b style=\"font-size:26px;color:#bb8222\">Reutilizar</b><br><span style=\"font-size:21px;color:#143325\">Darle otra vida a las cosas.</span>": "<b style=\"font-size:26px;color:#bb8222\">Riutilizzare</b><br><span style=\"font-size:21px;color:#143325\">Dare una seconda vita alle cose.</span>",
 "<b style=\"font-size:26px;color:#3b7fc6\">Reciclar</b><br><span style=\"font-size:21px;color:#143325\">Convertir lo usado en materia nueva.</span>": "<b style=\"font-size:26px;color:#3b7fc6\">Riciclare</b><br><span style=\"font-size:21px;color:#143325\">Trasformare ciò che è usato in materia nuova.</span>",
